package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorialLog
 */
public class MathUtils_factorialLog_TriageGen0Test {

    private static final double DELTA = 1e-15;

    @Test
    public void testFactorialLog_NegativeInput_ThrowsException() {
        try {
            MathUtils.factorialLog(-1);
            org.junit.Assert.fail("Expected IllegalArgumentException to be thrown for n < 0");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n > 0 for n!", e.getMessage());
        }
    }

    @Test
    public void testFactorialLog_Zero() {
        // For n=0, loop i=2 to 0 doesn't execute, returns 0.0
        // Note: log(0!) = log(1) = 0
        assertEquals(0.0, MathUtils.factorialLog(0), DELTA);
    }

    @Test
    public void testFactorialLog_One() {
        // For n=1, loop i=2 to 1 doesn't execute, returns 0.0
        // Note: log(1!) = log(1) = 0
        assertEquals(0.0, MathUtils.factorialLog(1), DELTA);
    }

    @Test
    public void testFactorialLog_Two() {
        // For n=2, logSum = log(2)
        double expected = Math.log(2.0);
        assertEquals(expected, MathUtils.factorialLog(2), DELTA);
    }

    @Test
    public void testFactorialLog_Three() {
        // For n=3, logSum = log(2) + log(3)
        double expected = Math.log(2.0) + Math.log(3.0);
        assertEquals(expected, MathUtils.factorialLog(3), DELTA);
    }

    @Test
    public void testFactorialLog_LargeValue() {
        // For n=5, logSum = log(2) + log(3) + log(4) + log(5)
        double expected = Math.log(2.0) + Math.log(3.0) + Math.log(4.0) + Math.log(5.0);
        assertEquals(expected, MathUtils.factorialLog(5), DELTA);
    }
}
